import { useState, useEffect } from "react"
import "../defaultresort/roomcarts.css"

import Skeleton from 'react-loading-skeleton'
import 'react-loading-skeleton/dist/skeleton.css'

const AllRoomsList = () => {

    let [ store, setStore ] = useState([]);
    let [ loading, setLoading ] = useState(true);

    const getdata = () => {
        try{
            fetch("http://localhost:1234/room")
            .then( res => res.json() )
            .then( info => {
                setStore(info)
            })
        }catch(error){
            console.error(" Data fetching is not processed ")
        }finally{
            se
        }
    }

    useEffect( () => {
        getdata()
    }, [])

    // const handelinput = (rooms) => {

    //     const inputes = window.prompt(" Enter your Email Id ");

    //     const roomdetails = {
    //         "email" : inputes,
    //         "rooms" : rooms
    //     }

    //     const url = "http://localhost:1111/main/"
    //     const postdata = {
    //         headers : { 'Content-type' : 'application/json' },
    //         method  : 'post',
    //         body    : JSON.stringify( roomdetails )
    //     }

    //     // console.log(postdata);

    //     try{ 

    //         fetch(url, postdata)
    //         .then( res => res.json() )
    //         .then( info => {
    //             alert( info.infos )
    //         })
    //     }catch(error){
    //         console.log(" Data process failed.... ");
    //     }

    // }

    return(
            <div className="container mt-5 " >
                <h2 className="fw-bolder ms-md-5" > LIST OF ROOM AVAILABLE </h2>
                    <div className="row " >
                        {
                            store.map( ( value, index ) => {
                                return(
                                    <div className="col-md-4 mt-4" key={index}>
                                        <div className=" card hovers rounded-5 p-2"  >
                                            {loading ? ( <Skeleton height={200} duration={0.8} baseColor="#c0c0c0" highlightColor="#f0f0f0" /> ) : ( <img src={value.image} alt="images" className=" p-2 rounded-5" /> )}  
                                            <div className=" card-body " >
                                                <h3 className="card-title fw-bold"> {loading ? ( <Skeleton width={`60%`} duration={0.8} baseColor="#c0c0c0" highlightColor="#f0f0f0" /> ) : `Room : ${value.rooms}` }  </h3>
                                                {loading ? (<Skeleton width={`60%`} count={2} duration={0.8} baseColor="#c0c0c0" highlightColor="#f0f0f0" />) : <div>  1hr/50m <br/> Tue 18/2 to Sat 22/2 </div>  }  
                                                <h3 className=" fw-bold " > { loading ? ( <Skeleton width={`60%`} count={2} duration={0.8} baseColor="#c0c0c0" highlightColor="#f0f0f0" /> ) : `from : $ 200` }  </h3>
                                            </div>
                                        </div>
                                    </div>
                                )
                            })
                        }
                    </div>
            </div>       
    )
}

export default AllRoomsList
